#!/bin/sh
# Headers Claude Code sends to the Code with Beto MCP (generated by
# scripts/build-claude-plugin.ts).
#
# No key file: prints {} and Claude Code signs in with OAuth (run /mcp).
# Key file: sends it as a bearer token. Get a key at
# https://codewithbeto.dev/profile, then:
#   mkdir -p ~/.config/codewithbeto
#   pbpaste > ~/.config/codewithbeto/mcp-api-key   # or paste it with any editor
#   chmod 600 ~/.config/codewithbeto/mcp-api-key

key_file="${XDG_CONFIG_HOME:-$HOME/.config}/codewithbeto/mcp-api-key"

if [ -r "$key_file" ]; then
  key=$(tr -d ' \t\r\n' < "$key_file")
  case "$key" in
    cwb_mcp_*)
      printf '{"Authorization":"Bearer %s"}\n' "$key"
      exit 0
      ;;
  esac
fi

printf '{}\n'
